import{_ as o,C as n,c as l,o as c,ag as i,j as t,G as r,a as s}from"./chunks/framework.Bw-5EFTY.js";const _=JSON.parse('{"title":"Referral Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings-and-customization/referral-settings.md","filePath":"guide/settings-and-customization/referral-settings.md","lastUpdated":1752126145000}'),u={name:"guide/settings-and-customization/referral-settings.md"};function g(f,e,d,p,h,m){const a=n("ZoomableImage");return c(),l("div",null,[e[0]||(e[0]=i('<h1 id="referral-settings" tabindex="-1">Referral Settings <a class="header-anchor" href="#referral-settings" aria-label="Permalink to &quot;Referral Settings&quot;">​</a></h1><p>The Referral Settings section allows you to configure the core rules and formats for your affiliate program, including how commissions are calculated, links are structured, and tracking is handled.</p><h3 id="accessing-referral-settings" tabindex="-1">Accessing Referral Settings <a class="header-anchor" href="#accessing-referral-settings" aria-label="Permalink to &quot;Accessing Referral Settings&quot;">​</a></h3><p>To access this section, navigate from your WordPress dashboard to <strong>FluentAffiliate → Settings → Referral Settings</strong>.</p><h3 id="link-commission-settings" tabindex="-1">Link &amp; Commission Settings <a class="header-anchor" href="#link-commission-settings" aria-label="Permalink to &quot;Link &amp; Commission Settings&quot;">​</a></h3><p>These settings define the structure of your affiliate links and the default commission rates.</p><ul><li><strong>Referral Variable:</strong> Define the variable used in referral links. The example shown is <code>ref</code>.</li><li><strong>Default Referral Format:</strong> Choose the default format for how referral links will be generated. The image shows &quot;Affiliate ID&quot; as the selected option.</li><li><strong>Rate:</strong> Set the standard commission rate for referrals, which can be a percentage or a fixed amount. The example value is 20 percent.</li></ul>',7)),t("p",null,[r(a,{src:"/guide/public/images/settings-and-customization/referral/referral-settings-overview.webp",alt:"Referral Settings"})]),e[1]||(e[1]=i('<h3 id="financial-formatting" tabindex="-1">Financial Formatting <a class="header-anchor" href="#financial-formatting" aria-label="Permalink to &quot;Financial Formatting&quot;">​</a></h3><p>Configure how monetary values and numbers are displayed across the plugin.</p><ul><li><strong>Currency:</strong> Select the primary currency for your store&#39;s transactions and affiliate payouts. &quot;United States Dollar&quot; is the example shown.</li><li><strong>Number Format:</strong> Choose the character style for separating thousands in numerical values. Options include US Style (1,000,00.00) and EU Style (1.000,00,00).</li><li><strong>Currency Symbol Position:</strong> Choose whether the currency symbol appears Before ($10) or After (10$) the amount.</li></ul><h3 id="tracking-credit-rules" tabindex="-1">Tracking &amp; Credit Rules <a class="header-anchor" href="#tracking-credit-rules" aria-label="Permalink to &quot;Tracking &amp; Credit Rules&quot;">​</a></h3><p>Define the logic for how affiliates are credited for referrals and how long they are tracked.</p><ul><li><strong>Credit:</strong> Determine which affiliate receives credit for a referral. You can credit the <strong>First Affiliate</strong> or the <strong>Last Affiliate</strong>.</li><li><strong>Cookie Duration:</strong> Set the duration of the cookie used to track referrals, specified in days. The example shows a duration of 30 days.</li></ul>',6)),t("p",null,[r(a,{src:"/guide/public/images/settings-and-customization/referral/recurring-commission-settings.webp",alt:"Recurring Settings"})]),e[2]||(e[2]=i('<h3 id="page-cost-subscription-settings" tabindex="-1">Page, Cost, &amp; Subscription Settings <a class="header-anchor" href="#page-cost-subscription-settings" aria-label="Permalink to &quot;Page, Cost, &amp; Subscription Settings&quot;">​</a></h3><p>This section allows you to configure page assignments, cost exclusions, and rules for self-referrals and subscriptions.</p><ul><li><p><strong>Affiliate Area:</strong> Select the page you want to use for your affiliate portal. You can use the <code>[fluent_affiliate_portal]</code> shortcode on this page. Clicking the plus icon will open an &quot;Add Page&quot; pop-up where you can enter a new &quot;Page Title&quot; and click &quot;Add&quot; to create it.</p></li><li><p><strong>Exclude Shipping:</strong> Enable this option to exclude shipping costs from the calculation of referral commissions.</p></li><li><p><strong>Exclude Tax:</strong> Enable this to exclude tax amounts from the calculation of referral commissions.</p></li><li><p><strong>Disable Self Referral:</strong> Enable this to prevent affiliates from earning commissions on their own purchases.</p></li><li><p><strong>Affiliate Commission on Subscription Renewal (Coming soon):</strong> This is an upcoming feature that will enable you to credit the main affiliate on subscription renewals.</p></li></ul>',3)),t("p",null,[r(a,{src:"/guide/public/images/settings-and-customization/referral/cost-tax-settings.webp",alt:"Cost and Tax Settings"})]),e[3]||(e[3]=t("p",null,[s("After configuring all your settings, click the "),t("strong",null,"Save Settings"),s(" button to apply the changes.")],-1))])}const b=o(u,[["render",g]]);export{_ as __pageData,b as default};
